import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.BS0bAV7E.js";const f=JSON.parse('{"title":"Internals: OTA/A-B mechanics","description":"","frontmatter":{},"headers":[],"relativePath":"internals/ota-ab.md","filePath":"internals/ota-ab.md"}'),s={name:"internals/ota-ab.md"};function n(r,e,l,c,h,d){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="internals-ota-a-b-mechanics" tabindex="-1">Internals: OTA/A-B mechanics <a class="header-anchor" href="#internals-ota-a-b-mechanics" aria-label="Permalink to &quot;Internals: OTA/A-B mechanics&quot;">​</a></h1><p><code>kernel/ota/ota_ab.{c,h}</code> + <code>ota_update.{c,h}</code>.</p><h2 id="slot-state-machine" tabindex="-1">Slot state machine <a class="header-anchor" href="#slot-state-machine" aria-label="Permalink to &quot;Slot state machine&quot;">​</a></h2><p>Each slot carries: kernel image, grub.cfg stanza, state (booting / successful / failed). The boot flag selects the active slot; GRUB&#39;s menu reads it (the ISO entry consults it, the force entries override it).</p><h2 id="install-onto-the-inactive-slot" tabindex="-1">Install onto the inactive slot <a class="header-anchor" href="#install-onto-the-inactive-slot" aria-label="Permalink to &quot;Install onto the inactive slot&quot;">​</a></h2><p><code>update install &lt;slot&gt;</code> writes the verified package&#39;s kernel onto the INACTIVE slot and sets the boot flag. You keep running on the current slot until reboot - a failed write never touches your running system.</p><h2 id="first-boot-after-flip" tabindex="-1">First boot after flip <a class="header-anchor" href="#first-boot-after-flip" aria-label="Permalink to &quot;First boot after flip&quot;">​</a></h2><p>The new slot boots in &quot;booting&quot; state; a successful userspace start marks it &quot;successful&quot; (the E2E walks this); if it never confirms, the flag falls back - that, plus the manual force entries, is the rollback story.</p><h2 id="verification-chain" tabindex="-1">Verification chain <a class="header-anchor" href="#verification-chain" aria-label="Permalink to &quot;Verification chain&quot;">​</a></h2><p>Manifest (update.json) -&gt; package SHA256 -&gt; signature. All three must pass before install touches a slot; failures refuse with the stage named.</p><h2 id="the-in-kernel-grub-payload" tabindex="-1">The in-kernel GRUB payload <a class="header-anchor" href="#the-in-kernel-grub-payload" aria-label="Permalink to &quot;The in-kernel GRUB payload&quot;">​</a></h2><p><code>tools/embed_grub.py</code> embeds boot.img + a grub-mkimage-built core.img (the module set the on-disk grub.cfg needs) into the kernel as generated C data - that is how <code>install</code>/<code>abdisk</code>/ <code>grub-install</code> write bootable disks with zero external files (the &quot;rule-9 self-hosting&quot; surface).</p>',12)])])}const b=t(s,[["render",n]]);export{f as __pageData,b as default};
